#' Synthetic Difference-in-Differences
#'
#' 
#' @param data .
#' @param outcome .
#' @param unit .
#' @param time .
#' @param predictors Time-varying covariates partialled out of the outcome
#'   with common coefficients, estimated jointly with the unit and time weights
#'   (must be observed in every period and unaffected by the treatment).
#' @param treatedUnit .
#' @param extraTreated Further units treated in the same first period. The
#'   estimator needs simultaneous adoption.
#' @param treatmentTime .
#' @param donorExclude .
#' @param estimator .
#' @param seMethod .
#' @param seReps .
#' @param seed .
#' @param showPath .
#' @param showGuide .
#' @param showHelp .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$weights} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$timeWeights} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$covCoef} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$effectCurve} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pathTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pathsPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$gapsPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
sdid <- function(
    data,
    outcome,
    unit,
    time,
    predictors,
    treatedUnit,
    extraTreated = "",
    treatmentTime = 2000,
    donorExclude = "",
    estimator = "sdid",
    seMethod = "placebo",
    seReps = 200,
    seed = 1,
    showPath = FALSE,
    showGuide = FALSE,
    showHelp = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("sdid requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(unit)) unit <- jmvcore::resolveQuo(jmvcore::enquo(unit))
    if ( ! missing(time)) time <- jmvcore::resolveQuo(jmvcore::enquo(time))
    if ( ! missing(predictors)) predictors <- jmvcore::resolveQuo(jmvcore::enquo(predictors))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(unit), unit, NULL),
            `if`( ! missing(time), time, NULL),
            `if`( ! missing(predictors), predictors, NULL))


    options <- sdidOptions$new(
        outcome = outcome,
        unit = unit,
        time = time,
        predictors = predictors,
        treatedUnit = treatedUnit,
        extraTreated = extraTreated,
        treatmentTime = treatmentTime,
        donorExclude = donorExclude,
        estimator = estimator,
        seMethod = seMethod,
        seReps = seReps,
        seed = seed,
        showPath = showPath,
        showGuide = showGuide,
        showHelp = showHelp)

    analysis <- sdidClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

